import { type Action, actionLabel } from "./prompt.ts";
import type { ThreadId } from "./selection.ts";
import {
  Binder,
  cls,
  mountStyle,
  type PostRenderEventBus,
  ref,
  sanitize,
  showKeyed,
  type View,
} from "./vamp.ts";
import type { AppEvent } from "./view.ts";

export type { Action };

export type State = {
  /** The text the user highlighted, or null when nothing is selected. */
  selection: string | null;
  /** The live selection intersects a committed mark, so no action is offered. */
  overlapping: boolean;
  query: string;
  /** The passages in this thread that already own a thread, offered as a way
   * back into them when nothing is selected. */
  marks: ReadonlyArray<{ thread: ThreadId; text: string }>;
};

/** Where the live selection ended, in viewport coordinates: the popup is
 * fixed-position, so it needs no knowledge of which pane scrolled. */
export type PopupState = { at: { x: number; y: number } };

export type Msg =
  | { type: "ACTION"; action: Action }
  /** Open the reflect layer on this passage without an action, so the user can
   * type their own question into the pane's composer. */
  | { type: "ASK" }
  | { type: "QUERY_CHANGED"; query: string }
  /** One of the existing passages was picked out of the list. */
  | { type: "MARK_CLICKED"; thread: ThreadId };

const paneClass = cls("learning-pane");
const popupClass = cls("selection-popup");
const emptyClass = cls("learning-empty");
const quoteClass = cls("learning-quote");
const actionsClass = cls("learning-actions");
const warnClass = cls("learning-warn");
const markListClass = cls("learning-mark-list");

mountStyle(`
.${paneClass} {
  position: sticky;
  top: 4rem;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  border-left: 1px solid rgba(0, 0, 0, 0.1);
  padding-left: 1.5rem;
}
.${emptyClass} {
  opacity: 0.5;
  font-style: italic;
}
.${markListClass} {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}
.${markListClass} button {
  font: inherit;
  font-size: 0.85rem;
  text-align: left;
  width: 100%;
  padding: 0.35rem 0.5rem;
  border: none;
  border-left: 3px solid #f0b429;
  background: rgba(0, 0, 0, 0.03);
  cursor: pointer;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.${markListClass} button:hover {
  background: rgba(0, 0, 0, 0.08);
}
.${warnClass} {
  font-style: italic;
  color: #a35200;
}
.${quoteClass} {
  white-space: pre-wrap;
  border-left: 3px solid #f0b429;
  padding-left: 0.75rem;
  max-height: 12rem;
  overflow-y: auto;
  font-size: 0.9rem;
}
.${actionsClass} {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 0.5rem;
}
.${actionsClass} button {
  font: inherit;
  text-align: left;
  padding: 0.5rem 0.75rem;
}
.${actionsClass} textarea {
  font: inherit;
  padding: 0.5rem;
  resize: vertical;
}
.${popupClass} {
  position: fixed;
  z-index: 10;
  transform: translate(-50%, 0.5rem);
  width: 16rem;
  padding: 0.5rem;
  border-radius: 0.5rem;
  border: 1px solid rgba(0, 0, 0, 0.15);
  background: #fff;
  box-shadow: 0 0.5rem 1.5rem rgba(0, 0, 0, 0.18);
}
`);

/** The same three affordances as the pane, floated next to the passage the
 * user just dragged. This is the only way into a reflection thread when the
 * pane is not on screen: at layer 0, and out of the reflect thread itself. */
export class SelectionPopup implements View<PopupState, Msg> {
  container: HTMLElement;
  /** The popup is portalled to the body rather than rendered where it is
   * mounted: it floats over a pane, and the panes are scrolling grid columns
   * that would clip it and reserve layout for it. */
  private readonly portal: HTMLElement;
  private b: Binder<PopupState>;

  constructor(
    container: HTMLElement,
    dispatch: (msg: Msg) => void,
    initialState: PopupState,
  ) {
    const explainRef = ref("popup-explain");
    const quizRef = ref("popup-quiz");
    const askRef = ref("popup-ask");

    this.container = container;
    this.portal = document.createElement("div");
    this.portal.className = `${popupClass} ${actionsClass}`;
    this.portal.innerHTML = sanitize`
      <button type="button" data-ref="${explainRef}">${actionLabel({ type: "explain" })}</button>
      <button type="button" data-ref="${quizRef}">${actionLabel({ type: "quiz" })}</button>
      <button type="button" data-ref="${askRef}">Ask your own question…</button>
    `;
    document.body.append(this.portal);
    this.b = new Binder(this.portal, initialState);

    // Selecting text and then reaching for the popup collapses the browser
    // selection on mousedown, which would dismiss the popup before the click
    // lands; the anchor is already captured, so the default is not wanted.
    this.portal.addEventListener("mousedown", (e: MouseEvent) => {
      e.preventDefault();
    });
    this.b
      .ref(explainRef)
      .addEventListener("click", () =>
        dispatch({ type: "ACTION", action: { type: "explain" } }),
      );
    this.b
      .ref(quizRef)
      .addEventListener("click", () =>
        dispatch({ type: "ACTION", action: { type: "quiz" } }),
      );
    // A textarea here cannot be typed into: the popup suppresses mousedown to
    // keep the selection alive, so it can never take focus. The composer in the
    // pane can, so this hands off to it.
    this.b
      .ref(askRef)
      .addEventListener("click", () => dispatch({ type: "ASK" }));

    this.b.bindContainerStyle((s) => ({
      left: `${s.at.x}px`,
      top: `${s.at.y}px`,
    }));
  }

  sync(state: PopupState): void {
    this.b.sync(state);
  }

  destroy(): void {
    this.b.cleanup();
    this.portal.remove();
  }
}

export type PaneCtx = { bus: PostRenderEventBus<AppEvent> };

/** One already-opened passage in the list. Its own view so the list can be
 * keyed by thread rather than rebuilt on every sync. */
class MarkItem implements View<{ text: string }, { type: "CLICK" }> {
  container: HTMLElement;
  private b: Binder<{ text: string }>;

  constructor(
    container: HTMLElement,
    dispatch: (msg: { type: "CLICK" }) => void,
    initialState: { text: string },
  ) {
    const buttonRef = ref("mark-item");
    container.innerHTML = sanitize`<button type="button" data-ref="${buttonRef}"></button>`;
    this.container = container;
    this.b = new Binder(container, initialState);
    this.b
      .ref(buttonRef)
      .addEventListener("click", () => dispatch({ type: "CLICK" }));
    this.b.bindText(buttonRef, (s) => s.text);
  }

  sync(state: { text: string }): void {
    this.b.sync(state);
  }

  destroy(): void {
    this.b.cleanup();
    this.container.innerHTML = "";
  }
}

export class LearningPane implements View<State, Msg, PaneCtx> {
  container: HTMLElement;
  private b: Binder<State>;
  private readonly unsubscribe: () => void;

  constructor(
    container: HTMLElement,
    dispatch: (msg: Msg) => void,
    initialState: State,
    ctx: PaneCtx,
  ) {
    const emptyRef = ref("empty");
    const bodyRef = ref("body");
    const quoteRef = ref("quote");
    const explainRef = ref("explain");
    const quizRef = ref("quiz");
    const queryRef = ref("query");
    const warnRef = ref("warn");
    const markListRef = ref("mark-list");

    container.className = paneClass;
    container.innerHTML = sanitize`
      <p class="${emptyClass}" data-ref="${emptyRef}">Select some text to get started.</p>
      <ul class="${markListClass}" data-ref="${markListRef}"></ul>
      <p class="${warnClass}" data-ref="${warnRef}">Select a non-overlapping section.</p>
      <div class="${actionsClass}" data-ref="${bodyRef}">
        <blockquote class="${quoteClass}" data-ref="${quoteRef}"></blockquote>
        <button type="button" data-ref="${explainRef}">I don't understand this.</button>
        <button type="button" data-ref="${quizRef}">Quiz me on this.</button>
        <textarea data-ref="${queryRef}" rows="2" placeholder="Ask your own question…"></textarea>
      </div>
    `;
    this.container = container;
    this.b = new Binder(container, initialState);

    this.b
      .ref(explainRef)
      .addEventListener("click", () =>
        dispatch({ type: "ACTION", action: { type: "explain" } }),
      );
    this.b
      .ref(quizRef)
      .addEventListener("click", () =>
        dispatch({ type: "ACTION", action: { type: "quiz" } }),
      );

    const query = this.b.ref<HTMLTextAreaElement>(queryRef);
    query.addEventListener("input", () => {
      dispatch({ type: "QUERY_CHANGED", query: query.value });
    });
    query.addEventListener("keydown", (e: KeyboardEvent) => {
      if (e.key !== "Enter" || e.shiftKey) return;
      e.preventDefault();
      const text = query.value.trim();
      if (text === "") return;
      dispatch({ type: "ACTION", action: { type: "query", text } });
    });

    // The popup hands the question over to this box: it cannot take focus
    // itself without dropping the selection, so the pane takes it here, once
    // the pane is actually on screen.
    this.unsubscribe = ctx.bus.subscribe((event) => {
      if (event.type === "learning:focus-query") query.focus();
    });

    this.b.bindVisible(emptyRef, (s) => s.selection === null && !s.overlapping);
    this.b.bindVisible(
      markListRef,
      (s) => s.selection === null && !s.overlapping && s.marks.length > 0,
    );
    this.b.bindList(markListRef, "li", (s) =>
      s.marks.map((mark) =>
        showKeyed(mark.thread, MarkItem, { text: mark.text }, {}, () =>
          dispatch({ type: "MARK_CLICKED", thread: mark.thread }),
        ),
      ),
    );
    this.b.bindVisible(warnRef, (s) => s.overlapping);
    this.b.bindVisible(bodyRef, (s) => s.selection !== null && !s.overlapping);
    this.b.bindText(quoteRef, (s) => s.selection ?? "");
    this.b.bindValue(queryRef, (s) => s.query);
  }

  sync(state: State): void {
    this.b.sync(state);
  }

  destroy(): void {
    this.unsubscribe();
    this.b.cleanup();
    this.container.innerHTML = "";
  }
}

import type Anthropic from "@anthropic-ai/sdk";
import type { ThreadSnapshot } from "./persistence.ts";
import {
  type Action,
  askTurn,
  contextSeed,
  LEARNING_SYSTEM,
  threadAskTurn,
  threadSeed,
} from "./prompt.ts";
import type { Anchor, Mark, ThreadId } from "./selection.ts";
import type { Tool, ToolName, TurnResult } from "./thread.ts";
import { type Socket, Thread } from "./thread.ts";

export type { Action };

/** The two ways a thread can be opened: off a passage of its parent, or off
 * the parent thread as a whole. Only the passage kind paints a highlight. */
export type Origin =
  | { type: "passage"; anchor: Anchor; action: Action }
  | { type: "thread"; parent: ThreadId; action: Action };

/** The thread this one was opened from. */
export function parentOf(origin: Origin): ThreadId {
  return origin.type === "passage" ? origin.anchor.thread : origin.parent;
}

/** What a child thread is given beyond its seed. */
export type ChildOpts = {
  tools?: Record<ToolName, Tool>;
  /** The rendered knowledge graph, injected into the seed of a top-level
   * learning thread. */
  graph?: string;
  yieldSchema?: Anthropic.Tool.InputSchema | "text" | "void";
};

export type TreeNode = {
  id: ThreadId;
  /** null only for the root task thread. */
  origin: Origin | null;
  thread: Thread;
  /** Creation order; a passage child's `origin.anchor` is its highlight. */
  children: ThreadId[];
  activeChild: ThreadId | null;
  draft: string;
};

/** The tree of threads. Every thread but the root was opened from its parent,
 * either off a passage of it - so a thread and the highlight over its parent
 * are the same edge seen from either end - or off the thread as a whole.
 * Threads are never destroyed or reparented. */
export class ThreadTree {
  private readonly threads = new Map<ThreadId, TreeNode>();
  private nextId = 0;
  root: ThreadId;
  private readonly socket: Socket;
  /** Attached to every thread the tree owns, so a stream anywhere in the
   * tree re-syncs the app. */
  private readonly onChange: () => void;

  constructor(socket: Socket, root: Thread, onChange: () => void) {
    this.socket = socket;
    this.onChange = onChange;
    this.root = this.add(null, root);
  }

  get(id: ThreadId): TreeNode {
    const node = this.threads.get(id);
    if (!node) throw new Error(`unknown thread ${id}`);
    return node;
  }

  /** Seeds a child thread from the parent's own seed plus its transcript
   * up to `anchor`, links it in, and makes it the parent's active child. The
   * caller starts it: the tree does not own the request lifecycle. */
  open(anchor: Anchor, action: Action, opts: ChildOpts = {}): ThreadId {
    const parent = this.get(anchor.thread);
    const thread = new Thread(this.socket, {
      system: LEARNING_SYSTEM,
      seed: contextSeed(
        typeof parent.thread.seed === "string" ? parent.thread.seed : undefined,
        parent.thread.messages,
        anchor,
        opts.graph,
      ),
      initialTurns: [
        {
          role: "user",
          content: askTurn(anchor, parent.thread.messages, action),
        },
      ],
      tools: opts.tools,
      yieldSchema: opts.yieldSchema,
    });
    const id = this.add({ type: "passage", anchor, action }, thread);
    parent.children.push(id);
    parent.activeChild = id;
    return id;
  }

  /** Seeds a child from the whole of `parent`'s transcript, with no passage:
   * it paints no highlight, and any number of them can hang off one parent. */
  openThread(parent: ThreadId, action: Action, opts: ChildOpts = {}): ThreadId {
    const node = this.get(parent);
    const thread = new Thread(this.socket, {
      system: LEARNING_SYSTEM,
      seed: threadSeed(
        typeof node.thread.seed === "string" ? node.thread.seed : undefined,
        node.thread.messages,
        opts.graph,
      ),
      initialTurns: [{ role: "user", content: threadAskTurn(action) }],
      tools: opts.tools,
      yieldSchema: opts.yieldSchema,
    });
    const id = this.add({ type: "thread", parent, action }, thread);
    node.children.push(id);
    node.activeChild = id;
    return id;
  }

  /** What a child thread settled with, once it has yielded. The parent renders
   * threads it never awaited, so the settled value has to be readable here. */
  result(id: ThreadId): TurnResult | undefined {
    return this.get(id).thread.result;
  }

  /** The highlights to draw over `id`'s transcript: one per passage child.
   * Thread-level children have no passage and so paint nothing. */
  marks(id: ThreadId): Mark[] {
    const out: Mark[] = [];
    for (const child of this.get(id).children) {
      const origin = this.get(child).origin;
      if (!origin) throw new Error("child thread without an origin");
      if (origin.type === "passage")
        out.push({ thread: child, anchor: origin.anchor });
    }
    return out;
  }

  /** The thread-level children of `id`, in creation order. */
  threadChildren(
    id: ThreadId,
  ): ReadonlyArray<{ thread: ThreadId; action: Action }> {
    const out: { thread: ThreadId; action: Action }[] = [];
    for (const child of this.get(id).children) {
      const origin = this.get(child).origin;
      if (!origin) throw new Error("child thread without an origin");
      if (origin.type === "thread")
        out.push({ thread: child, action: origin.action });
    }
    return out;
  }

  /** root -> id, for the depth indicator. */
  path(id: ThreadId): ThreadId[] {
    const out: ThreadId[] = [];
    let at: ThreadId | undefined = id;
    while (at) {
      out.unshift(at);
      const from: Origin | null = this.get(at).origin;
      at = from ? parentOf(from) : undefined;
    }
    return out;
  }

  /** The id counter, persisted so a restored tree cannot re-mint an id. */
  get nextThreadId(): number {
    return this.nextId;
  }

  /** Every node, in creation order. */
  nodes(): ReadonlyArray<TreeNode> {
    return [...this.threads.values()];
  }

  /** Rebuilds a tree from persisted snapshots rather than from a root thread.
   * `threadOf` mints the `Thread` for each snapshot, so the caller owns tool
   * wiring, which the snapshot deliberately does not carry. */
  static restore(
    socket: Socket,
    snapshots: ReadonlyArray<ThreadSnapshot>,
    root: ThreadId,
    nextId: number,
    onChange: () => void,
    threadOf: (snapshot: ThreadSnapshot) => Thread,
  ): ThreadTree {
    const rootSnapshot = snapshots.find((s) => s.id === root);
    if (!rootSnapshot) throw new Error(`no snapshot for root ${root}`);
    const tree = new ThreadTree(socket, threadOf(rootSnapshot), onChange);
    const rootThread = tree.get(tree.root).thread;
    tree.threads.clear();
    for (const snapshot of snapshots) {
      const thread = snapshot.id === root ? rootThread : threadOf(snapshot);
      tree.threads.set(snapshot.id, tree.node(snapshot, thread));
    }
    tree.root = root;
    tree.nextId = nextId;
    return tree;
  }

  private node(snapshot: ThreadSnapshot, thread: Thread): TreeNode {
    thread.onChange = this.onChange;
    return {
      id: snapshot.id,
      origin: snapshot.origin,
      thread,
      children: [...snapshot.children],
      activeChild: snapshot.activeChild,
      draft: snapshot.draft,
    };
  }

  private add(origin: Origin | null, thread: Thread): ThreadId {
    const id = `t${this.nextId++}` as ThreadId;
    thread.onChange = this.onChange;
    this.threads.set(id, {
      id,
      origin,
      thread,
      children: [],
      activeChild: null,
      draft: "",
    });
    return id;
  }
}

import type Anthropic from "@anthropic-ai/sdk";
import { citationText } from "./citation.ts";
import type { Interaction } from "./interactions.ts";
import { type Anchor, anchorText, type ThreadId } from "./selection.ts";
import type { Message, MessageIdx } from "./thread.ts";

export type Action =
  | { type: "explain" }
  | { type: "quiz" }
  | { type: "review" }
  | { type: "ideas" }
  | { type: "query"; text: string };

/** Learning mode: the agent is explaining work that already happened, to a
 * user who chose the passage they are stuck on. */
export const LEARNING_SYSTEM = [
  "You are helping a user understand engineering work that was done for them.",
  "They will show you a transcript, and either point at a passage they picked",
  "out or ask about the thread as a whole. Answer about whatever they scoped",
  "it to specifically, in plain language, and assume the user has not followed",
  "the reasoning that produced it. Be concise, and do not restate the whole",
  "transcript back to them.",
  "",
  "You may be shown a knowledge graph: what we believe this user already",
  "understands, one line per node and edge, each with an id and a level on the",
  "scale 1 unfamiliar, 2 emerging, 3 working, 4 fluent. Pitch your answer to",
  "it: build on what they are fluent in and slow down on what they are not.",
  "The overview is titles only, so call the `get` tool with the ids of",
  "anything you are about to lean on to read its full description and the",
  "notes on this user. You cannot change the graph; do not offer to.",
].join(" ");

/** The context a learning thread is seeded with: its parent's own seed plus
 * the parent's transcript up to the anchor. `seed` is emitted verbatim -
 * wrapping or re-labelling it would nest the framing one layer deeper at
 * every level. The passage and the ask are not here: they are the thread's
 * first visible turn. */
export function contextSeed(
  seed: string | undefined,
  messages: ReadonlyArray<Message>,
  anchor: Anchor,
  graph?: string,
): string {
  const sections = [];
  // Only the topmost learning thread renders the graph: a deeper thread's
  // `seed` is its parent's, which already carries it, and repeating it would
  // show the model the same overview once per level.
  if (seed) sections.push(seed);
  else if (graph)
    sections.push(`What this user already understands:\n${graph}`);
  sections.push(transcript(visibleTo(messages, anchor)));
  return sections.join("\n\n");
}

/** The seed for a thread-level child: the parent's whole transcript, with the
 * graph carried the same way. The anchor-truncating sibling of `contextSeed`. */
export function threadSeed(
  seed: string | undefined,
  messages: ReadonlyArray<Message>,
  graph?: string,
): string {
  const sections = [];
  if (seed) sections.push(seed);
  else if (graph)
    sections.push(`What this user already understands:\n${graph}`);
  sections.push(transcript(messages));
  return sections.join("\n\n");
}

/** The opening turn for a thread-level child: the ask alone, with no quote,
 * because the scope is the whole thread. */
export function threadAskTurn(action: Action): string {
  return ask(action);
}

/** The user's opening turn: the passage they highlighted and what they asked
 * of it. Visible, because it is an interaction like any other. */
export function askTurn(
  anchor: Anchor,
  messages: ReadonlyArray<Message>,
  action: Action,
): string {
  const quote = anchorText(anchor, visibleTo(messages, anchor));
  return `Selected: "${quote}"\n\n${ask(action)}`;
}

/** The parent's transcript truncated after the message the selection ends in:
 * nothing later than the passage is context for asking about it. */
function visibleTo(
  messages: ReadonlyArray<Message>,
  anchor: Anchor,
): ReadonlyArray<Message> {
  return messages.slice(0, anchor.end.msg + 1);
}

/** Graph update mode: one detached pass over a single user interaction, whose
 * only output is whatever it writes to the graph through its tools. */
export const GRAPH_UPDATE_SYSTEM = [
  "You maintain a knowledge graph of what one user understands. You are shown",
  "a single interaction that user just made, in the context of the thread it",
  "happened in and the graph as it stands.",
  "",
  "Ask: what domain concepts is this interaction about, are they in the graph",
  "already, what understanding does the user demonstrate here, and does",
  "anything here read as a gap or a misconception. A node is a concept - an",
  "idea a person can understand or fail to understand - never a file, a",
  "message or a line of code. Set `level` from what the interaction reveals,",
  "on the scale 1 unfamiliar, 2 emerging, 3 working, 4 fluent. The scale",
  "cannot express a misconception - a confidently held wrong belief reads as",
  "fluent - so put misconceptions, and anything else about how this user holds",
  "the idea, in `notes`.",
  "",
  "Touch only what this interaction is about; leave the rest of the graph",
  "alone. Keep the graph small and coarse: update the node that already covers",
  "a concept rather than minting a second one for it, and split a concept only",
  "when the split expresses something real about this user's understanding. A",
  "concept the user merely brushed past does not need a node.",
  "",
  "Ground every note about this user in what they actually did. Each block of",
  "the transcript is labelled with its address, `@message:<thread>:<index>`,",
  "including the interaction itself. A claim about what this user understands",
  "or misunderstands must cite the addresses it rests on, written verbatim in",
  "the note; do not assert anything you cannot point at.",
  "",
  "Most interactions reveal nothing. If this one does not, change nothing and",
  "yield: doing nothing is the expected outcome, not a failure. The yield tool",
  "takes no input, and nothing you say outside the tools is read: the graph",
  "writes are the whole output of this thread, so do not narrate or summarize",
  "them.",
].join(" ");

/** Two blocks: the cacheable prefix - the base prompt, the thread's seed and
 * the transcript before the turn, all of which every earlier interaction in
 * this thread shares - then the volatile tail, which starts with the graph
 * because the previous update just rewrote it. */
export function graphUpdatePrompt(
  interaction: Interaction,
  graph: string,
): Anthropic.ContentBlockParam[] {
  const prefix = [GRAPH_UPDATE_PREAMBLE];
  if (interaction.prefix.seed)
    prefix.push(`How this thread was framed:\n${interaction.prefix.seed}`);
  if (interaction.prefix.messages.length > 0)
    prefix.push(
      `The thread up to this interaction:\n${transcript(interaction.prefix.messages, interaction.thread)}`,
    );
  return [
    {
      type: "text",
      text: prefix.join("\n\n"),
      cache_control: { type: "ephemeral" },
    },
    {
      type: "text",
      text: [
        `The knowledge graph as it stands:\n${graph}`,
        `The interaction, at ${citationText({ thread: interaction.thread, index: interaction.index })}:\nUser: ${interaction.text}`,
        GRAPH_UPDATE_QUESTIONS,
      ].join("\n\n"),
    },
  ];
}

const GRAPH_UPDATE_PREAMBLE =
  "Below is one interaction a user made while an engineering agent worked on a task for them, and the context it happened in.";

const GRAPH_UPDATE_QUESTIONS = [
  "What domain concepts does this interaction touch, and are they in the",
  "graph? What understanding does it demonstrate, and what does it suggest",
  "the user is missing? Update the graph so it reflects that, and nothing",
  "else - then yield.",
].join(" ");

/** With `thread`, every block is labelled with its address, so the model can
 * cite it back. Indices are positions in that thread's `messages`, which is
 * append-only, so an address stays valid for the life of the page. */
function transcript(
  messages: ReadonlyArray<Message>,
  thread?: ThreadId,
): string {
  return messages
    .map((m, i) => {
      const who = m.role === "user" ? "User" : "Assistant";
      const at = thread
        ? ` (${citationText({ thread, index: i as MessageIdx })})`
        : "";
      return `${who}${at}: ${line(m)}`;
    })
    .join("\n\n");
}

function line(message: Message): string {
  return message.type === "text"
    ? message.text
    : `[called tool ${message.call.name} with ${message.call.inputJson}]`;
}

/** How the thread was opened, shown at the top of its pane so the user can see
 * what they asked for. */
export function actionLabel(action: Action): string {
  switch (action.type) {
    case "explain":
      return "I don't understand this.";
    case "quiz":
      return "Quiz me on this.";
    case "review":
      return "Let's review what happened in this task.";
    case "ideas":
      return "Give me some ideas about what I can explore.";
    case "query":
      return action.text;
  }
}

/** What the user is asking for, in their own voice: this is a user turn now,
 * not a briefing written about them. */
function ask(action: Action): string {
  switch (action.type) {
    case "explain":
      return "I don't understand this. Explain what it means and why it is there.";
    case "quiz":
      return "Quiz me on this. Ask one question that checks whether I understand it, and wait for my answer.";
    case "review":
      return "Let's review what happened in this task. Name the handful of decisions and moments that actually mattered, and for each one say why it is worth my digging into, given what you know about what I already understand.";
    case "ideas":
      return "Give me some ideas about what I can explore. Suggest a few things in this task worth exploring or learning more about, pitched at what you know about what I do and do not understand.";
    case "query":
      return action.text;
  }
}

